//! GitHub API tools — 34 tools ported from agent-core-v2's `GITHUB_SPECS`
//! (`packages/agent-core-v2/src/agent/tools/github/github-tools.ts`).
//!
//! The spec table below is generated by `.tmp/extract-github-specs.mjs`;
//! names, descriptions, paths, query/body templates and field schemas
//! mirror the v2 definitions verbatim. Execution follows
//! `github-request.ts`: Bearer token auth, `X-GitHub-Api-Version`
//! 2022-11-28, `User-Agent: kimi-code`, 30s timeout, 5MB body cap,
//! and the rate-limit hint from `x-ratelimit-remaining`.

use std::time::Duration;

use futures_util::StreamExt;
use serde_json::{Value, json};

use crate::turn_loop::types::{ExecutableToolResult, ToolInfo};

/// Serializes every test that reads or writes the `GITHUB_TOKEN` /
/// `GH_TOKEN` / `GITHUB_API_URL` process environment. Environment variables
/// are global mutable state, so two such tests running in parallel flake
/// each other (one removes the variable the other just set) — hold this
/// lock for the entire test body, including the save/restore window.
#[cfg(test)]
pub(crate) static GITHUB_ENV_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

/// No-token error text, verbatim from v2 `github-request.ts`.
pub const GITHUB_NO_TOKEN_ERROR: &str = "No GitHub token configured. Set token in the [github] section of config.toml, or set the GITHUB_TOKEN (or GH_TOKEN) environment variable.";

const GITHUB_DEFAULT_BASE_URL: &str = "https://api.github.com";
const GITHUB_API_VERSION: &str = "2022-11-28";
const GITHUB_USER_AGENT: &str = "kimi-code";
const GITHUB_DEFAULT_ACCEPT: &str = "application/vnd.github+json";
const GITHUB_REQUEST_TIMEOUT_SECS: u64 = 30;
const GITHUB_MAX_RESPONSE_BODY_BYTES: usize = 5 * 1024 * 1024;

/// Argument kind used for validation and JSON-schema generation.
#[derive(Clone, Copy, PartialEq, Eq)]
enum FieldKind {
    /// String, min length 1.
    Str,
    /// String, any length.
    StrAny,
    /// Integer.
    Int,
    /// Boolean.
    Bool,
    /// Array of strings.
    StrArray,
    /// Array of tree-entry objects (GitHubCreateTree).
    TreeArray,
}

struct Field {
    name: &'static str,
    kind: FieldKind,
    required: bool,
    description: &'static str,
    min: Option<i64>,
    max: Option<i64>,
    enum_values: &'static [&'static str],
}

struct GitHubToolSpec {
    name: &'static str,
    description: &'static str,
    method: &'static str,
    /// Path template with `{arg}` placeholders (v2 path fn).
    path: &'static str,
    /// `(arg key, query key)` pairs (v2 query fn).
    query: &'static [(&'static str, &'static str)],
    /// `(arg key, body key)` pairs (v2 body fn).
    body: &'static [(&'static str, &'static str)],
    /// `(body key, arg name)` pairs whose value is base64-encoded (v2 Buffer.from).
    body_base64: &'static [(&'static str, &'static str)],
    /// `(body key, arg name, prefix)` — body value is `prefix + arg` (v2 template).
    body_prefix: &'static [(&'static str, &'static str, &'static str)],
    accept: Option<&'static str>,
    fields: &'static [Field],
}

