/// Tool definitions exposed to the model (name/description/schema).
pub fn github_tool_defs() -> Vec<ToolInfo> {
    SPECS
        .iter()
        .map(|spec| ToolInfo {
            name: spec.name.into(),
            description: spec.description.into(),
            input_schema: schema_for(spec),
        })
        .collect()
}

fn schema_for(spec: &GitHubToolSpec) -> Value {
    let mut properties = serde_json::Map::new();
    for field in spec.fields {
        properties.insert(field.name.to_string(), field_schema(field));
    }
    let mut schema = json!({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": properties,
        "additionalProperties": false,
    });
    let required: Vec<&str> = spec
        .fields
        .iter()
        .filter(|f| f.required)
        .map(|f| f.name)
        .collect();
    if !required.is_empty() {
        schema["required"] = json!(required);
    }
    schema
}

fn field_schema(field: &Field) -> Value {
    let mut schema = match field.kind {
        FieldKind::Str | FieldKind::StrAny => json!({ "type": "string" }),
        FieldKind::Int => json!({ "type": "integer" }),
        FieldKind::Bool => json!({ "type": "boolean" }),
        FieldKind::StrArray => json!({ "type": "array", "items": { "type": "string" } }),
        FieldKind::TreeArray => json!({
            "type": "array",
            "items": object_schema(TREE_ENTRY_FIELDS),
        }),
    };
    match field.kind {
        FieldKind::Str => {
            if let Some(min) = field.min {
                schema["minLength"] = json!(min);
            }
        }
        FieldKind::Int => {
            schema["minimum"] = json!(field.min.unwrap_or(-9007199254740991));
            schema["maximum"] = json!(field.max.unwrap_or(9007199254740991));
        }
        FieldKind::StrArray | FieldKind::TreeArray => {
            if let Some(min) = field.min {
                schema["minItems"] = json!(min);
            }
        }
        FieldKind::StrAny | FieldKind::Bool => {}
    }
    if !field.enum_values.is_empty() {
        schema["enum"] = json!(field.enum_values);
    }
    if !field.description.is_empty() {
        schema["description"] = json!(field.description);
    }
    schema
}

fn object_schema(fields: &[Field]) -> Value {
    let mut properties = serde_json::Map::new();
    for field in fields {
        properties.insert(field.name.to_string(), field_schema(field));
    }
    let mut schema = json!({
        "type": "object",
        "properties": properties,
        "additionalProperties": false,
    });
    let required: Vec<&str> = fields
        .iter()
        .filter(|f| f.required)
        .map(|f| f.name)
        .collect();
    if !required.is_empty() {
        schema["required"] = json!(required);
    }
    schema
}

// ── Execution ──────────────────────────────────────────────────────────────

/// Whether `tool_name` is one of the 34 GitHub tools (case-insensitive).
pub fn is_github_tool(tool_name: &str) -> bool {
    SPECS
        .iter()
        .any(|spec| spec.name.eq_ignore_ascii_case(tool_name))
}

/// v2 `mutating: true` specs (`GITHUB_MUTATING_TOOL_NAMES`) — excluded from
/// the default auto-approve allowlist, so they prompt in non-auto permission
/// modes (v2 `default-tool-approve.ts`).
static MUTATING_TOOLS: &[&str] = &[
    "GitHubCreateOrUpdateFile",
    "GitHubCreateTree",
    "GitHubCreateCommit",
    "GitHubUpdateRef",
    "GitHubCreateBranch",
    "GitHubCreateIssue",
    "GitHubUpdateIssue",
    "GitHubAddIssueComment",
    "GitHubCreatePR",
    "GitHubUpdatePR",
    "GitHubMergePR",
    "GitHubCreatePRReview",
];

/// Whether the tool mutates GitHub state (v2 `spec.mutating`).
pub fn is_mutating_tool(tool_name: &str) -> bool {
    MUTATING_TOOLS
        .iter()
        .any(|name| name.eq_ignore_ascii_case(tool_name))
}

/// Whether the tool is a read-only GitHub tool — the set v2 adds to the
/// default auto-approve allowlist (`GITHUB_READONLY_TOOL_NAMES`).
pub fn is_readonly_tool(tool_name: &str) -> bool {
    is_github_tool(tool_name) && !is_mutating_tool(tool_name)
}

/// Permission rule subject (v2 `spec.subject`): repo tools use `owner/repo`,
/// the search tools use the `q` argument, GetMe uses `me`.
pub fn rule_subject(tool_name: &str, args: &Value) -> Option<String> {
    let spec = SPECS
        .iter()
        .find(|spec| spec.name.eq_ignore_ascii_case(tool_name))?;
    if spec.name.eq_ignore_ascii_case("GitHubGetMe") {
        return Some("me".to_string());
    }
    if spec.fields.iter().any(|field| field.name == "q") {
        return args.get("q").and_then(Value::as_str).map(str::to_string);
    }
    match (arg_string(args, "owner"), arg_string(args, "repo")) {
        (Some(owner), Some(repo)) => Some(format!("{owner}/{repo}")),
        _ => None,
    }
}

/// Whether any GitHub token is resolvable from the host-provided `[github]`
/// config values or the environment (v2 `hasGitHubToken` — v2 gates tool
/// registration on this via the `when` clause).
pub fn has_token(credentials: Option<&GitHubCredentials>) -> bool {
    resolve_token(credentials).is_some()
}

/// Execute a GitHub tool by name (case-insensitive). `None` when the name is
/// not a GitHub tool — the caller falls back to the host path.
pub async fn execute_github_tool(
    tool_name: &str,
    args: &Value,
    credentials: Option<&GitHubCredentials>,
) -> Option<ExecutableToolResult> {
    let spec = SPECS
        .iter()
        .find(|spec| spec.name.eq_ignore_ascii_case(tool_name))?;
    Some(execute_spec(spec, args, credentials).await)
}

async fn execute_spec(
    spec: &GitHubToolSpec,
    args: &Value,
    credentials: Option<&GitHubCredentials>,
) -> ExecutableToolResult {
    let token = resolve_token(credentials);
    let base_url = resolve_base_url(credentials);
    execute_with_token(spec, args, token.as_deref(), Some(base_url.as_str())).await
}

/// Execution with an explicit token, so tests can exercise the no-token and
/// validation paths without touching the process environment.
async fn execute_with_token(
    spec: &GitHubToolSpec,
    args: &Value,
    token: Option<&str>,
    base_url: Option<&str>,
) -> ExecutableToolResult {
    if let Some(issues) = validate_args(spec, args) {
        return err_result(format!("Invalid arguments for {}: {issues}", spec.name));
    }
    let Some(token) = token else {
        return err_result(GITHUB_NO_TOKEN_ERROR.to_string());
    };
    let url = build_url(spec, args, base_url.unwrap_or(GITHUB_DEFAULT_BASE_URL));
    let query = build_query(spec, args);
    let body = build_body(spec, args);
    let response = github_request(spec, url, query, body, token).await;
    format_result(response)
}

/// Host-resolved `[github]` config values (v2 `configSection.ts`). Absent
/// fields fall back to the environment with v2 `envOverlay.ts` semantics:
/// config wins, env fills the gap.
#[derive(Clone, Debug, Default)]
pub struct GitHubCredentials {
    pub token: Option<String>,
    pub base_url: Option<String>,
}

/// Token resolution mirrors v2 `envOverlay.ts`: the config `[github].token`
/// wins, then `GITHUB_TOKEN`, then `GH_TOKEN`; empty/whitespace-only values
/// count as unset.
fn resolve_token(credentials: Option<&GitHubCredentials>) -> Option<String> {
    if let Some(value) = credentials.and_then(|c| c.token.as_deref()) {
        let trimmed = value.trim();
        if !trimmed.is_empty() {
            return Some(trimmed.to_string());
        }
    }
    for name in ["GITHUB_TOKEN", "GH_TOKEN"] {
        if let Ok(value) = std::env::var(name) {
            let trimmed = value.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_string());
            }
        }
    }
    None
}

/// Base URL mirrors v2 `envOverlay.ts`: the config `[github].baseUrl` wins,
/// then `GITHUB_API_URL`, then the default. Trailing slashes are stripped
/// like v2 `buildGitHubUrl`.
fn resolve_base_url(credentials: Option<&GitHubCredentials>) -> String {
    let mut configured: Option<String> = None;
    if let Some(value) = credentials.and_then(|c| c.base_url.as_deref()) {
        let trimmed = value.trim();
        if !trimmed.is_empty() {
            configured = Some(trimmed.to_string());
        }
    }
    if configured.is_none()
        && let Ok(value) = std::env::var("GITHUB_API_URL")
    {
        let trimmed = value.trim();
        if !trimmed.is_empty() {
            configured = Some(trimmed.to_string());
        }
    }
    configured
        .unwrap_or_else(|| GITHUB_DEFAULT_BASE_URL.to_string())
        .trim_end_matches('/')
        .to_string()
}

// ── Argument validation (v2 zod `safeParse` semantics) ───────────────────────

/// Returns the v2-style `Invalid arguments for {name}: ...` payload, or
/// `None` when the args are valid. Issues mirror zod v4's shape
/// (`code`/`expected`/`received`/`path`/`message`).
fn validate_args(spec: &GitHubToolSpec, args: &Value) -> Option<String> {
    let mut issues: Vec<Value> = Vec::new();
    for field in spec.fields {
        let Some(value) = args.get(field.name) else {
            if field.required {
                issues.push(invalid_type_issue(
                    field.name,
                    expected_type(field.kind),
                    "undefined",
                ));
            }
            continue;
        };
        if value.is_null() {
            if field.required {
                issues.push(invalid_type_issue(
                    field.name,
                    expected_type(field.kind),
                    "null",
                ));
            }
            continue;
        }
        match field.kind {
            FieldKind::Str | FieldKind::StrAny => {
                if let Value::String(s) = value {
                    if field.kind == FieldKind::Str && s.is_empty() {
                        issues.push(too_small_issue(field.name, 1));
                    }
                } else {
                    issues.push(invalid_type_issue(
                        field.name,
                        "string",
                        received_type(value),
                    ));
                }
            }
            FieldKind::Int => {
                if value.as_i64().is_none() {
                    issues.push(invalid_type_issue(
                        field.name,
                        "number",
                        received_type(value),
                    ));
                }
            }
            FieldKind::Bool => {
                if value.as_bool().is_none() {
                    issues.push(invalid_type_issue(
                        field.name,
                        "boolean",
                        received_type(value),
                    ));
                }
            }
            FieldKind::StrArray => {
                let valid = value
                    .as_array()
                    .is_some_and(|a| a.iter().all(Value::is_string));
                if !valid {
                    issues.push(invalid_type_issue(
                        field.name,
                        "array",
                        received_type(value),
                    ));
                }
            }
            FieldKind::TreeArray => {
                if !value.is_array() {
                    issues.push(invalid_type_issue(
                        field.name,
                        "array",
                        received_type(value),
                    ));
                }
            }
        }
    }
    if issues.is_empty() {
        None
    } else {
        Some(serde_json::to_string_pretty(&issues).unwrap_or_default())
    }
}

fn expected_type(kind: FieldKind) -> &'static str {
    match kind {
        FieldKind::Str | FieldKind::StrAny => "string",
        FieldKind::Int => "number",
        FieldKind::Bool => "boolean",
        FieldKind::StrArray | FieldKind::TreeArray => "array",
    }
}

fn received_type(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn invalid_type_issue(path: &str, expected: &str, received: &str) -> Value {
    json!({
        "code": "invalid_type",
        "expected": expected,
        "received": received,
        "path": [path],
        "message": format!("Invalid input: expected {expected}, received {received}"),
    })
}

fn too_small_issue(path: &str, minimum: i64) -> Value {
    json!({
        "code": "too_small",
        "minimum": minimum,
        "inclusive": true,
        "path": [path],
        "message": format!("Too small: expected string to have >={minimum} characters"),
    })
}

// ── URL / query / body building (v2 path/query/body fns) ────────────────────

fn build_url(spec: &GitHubToolSpec, args: &Value, base_url: &str) -> String {
    let mut path = String::new();
    let mut rest = spec.path;
    while let Some(start) = rest.find('{') {
        path.push_str(&rest[..start]);
        let end = rest[start..]
            .find('}')
            .map(|offset| start + offset)
            .expect("unterminated path placeholder");
        let key = &rest[start + 1..end];
        path.push_str(&encode_path_component(
            &arg_string(args, key).unwrap_or_default(),
        ));
        rest = &rest[end + 1..];
    }
    path.push_str(rest);
    format!("{base_url}{path}")
}

fn build_query(spec: &GitHubToolSpec, args: &Value) -> Option<String> {
    let mut pairs: Vec<String> = Vec::new();
    for (query_key, arg_key) in spec.query {
        let Some(value) = arg_string(args, arg_key) else {
            continue;
        };
        pairs.push(format!(
            "{}={}",
            encode_uri_component(query_key),
            encode_uri_component(&value)
        ));
    }
    if pairs.is_empty() {
        None
    } else {
        Some(format!("?{}", pairs.join("&")))
    }
}

fn build_body(spec: &GitHubToolSpec, args: &Value) -> Option<Value> {
    let mut map = serde_json::Map::new();
    for (body_key, arg_key) in spec.body {
        let Some(value) = args.get(*arg_key) else {
            continue;
        };
        if value.is_null() {
            continue;
        }
        map.insert((*body_key).to_string(), value.clone());
    }
    for (body_key, arg_key) in spec.body_base64 {
        let Some(value) = arg_string(args, arg_key) else {
            continue;
        };
        map.insert(
            (*body_key).to_string(),
            Value::String(base64_encode(value.as_bytes())),
        );
    }
    for (body_key, arg_key, prefix) in spec.body_prefix {
        let Some(value) = arg_string(args, arg_key) else {
            continue;
        };
        map.insert(
            (*body_key).to_string(),
            Value::String(format!("{prefix}{value}")),
        );
    }
    if map.is_empty() {
        None
    } else {
        Some(Value::Object(map))
    }
}

fn arg_string(args: &Value, key: &str) -> Option<String> {
    match args.get(key) {
        Some(Value::String(s)) => Some(s.clone()),
        Some(Value::Number(n)) => Some(n.to_string()),
        Some(Value::Bool(b)) => Some(b.to_string()),
        _ => None,
    }
}

/// JS `encodeURIComponent`: encodes everything except `A-Za-z0-9-_.!~*'()`.
fn encode_uri_component(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric()
            || matches!(
                b,
                b'-' | b'.' | b'_' | b'~' | b'!' | b'*' | b'\'' | b'(' | b')'
            )
        {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

/// WHATWG path percent-encode set — what fetch applies to the interpolated
/// path in v2. Encodes space, `"`, `#`, `<`, `>`, `?`, backtick, `{`, `}`,
/// and non-ASCII/control bytes; existing `%` escapes pass through.
fn encode_path_component(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric()
            || matches!(
                b,
                b'-' | b'.'
                    | b'_'
                    | b'~'
                    | b'!'
                    | b'$'
                    | b'&'
                    | b'\''
                    | b'('
                    | b')'
                    | b'*'
                    | b'+'
                    | b','
                    | b';'
                    | b'='
                    | b':'
                    | b'@'
                    | b'/'
                    | b'%'
            )
        {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

/// Standard base64 (RFC 4648) — v2 `Buffer.from(content, 'utf8').toString('base64')`.
fn base64_encode(input: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(input.len().div_ceil(3) * 4);
    for chunk in input.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = chunk.get(1).copied().unwrap_or(0) as u32;
        let b2 = chunk.get(2).copied().unwrap_or(0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(TABLE[(n >> 18) as usize & 63] as char);
        out.push(TABLE[(n >> 12) as usize & 63] as char);
        if chunk.len() > 1 {
            out.push(TABLE[(n >> 6) as usize & 63] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(TABLE[n as usize & 63] as char);
        } else {
            out.push('=');
        }
    }
    out
}

// ── HTTP request (v2 `github-request.ts` semantics) ───────────────────────

struct GitHubResponse {
    status: u16,
    ok: bool,
    body: String,
    error: Option<String>,
    rate_remaining: Option<i64>,
}

async fn github_request(
    spec: &GitHubToolSpec,
    url: String,
    query: Option<String>,
    body: Option<Value>,
    token: &str,
) -> GitHubResponse {
    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(GITHUB_REQUEST_TIMEOUT_SECS))
        .build()
    {
        Ok(client) => client,
        Err(e) => {
            return GitHubResponse {
                status: 0,
                ok: false,
                body: String::new(),
                error: Some(format!("network error: {e}")),
                rate_remaining: None,
            };
        }
    };
    let full_url = format!("{url}{}", query.unwrap_or_default());
    let method =
        reqwest::Method::from_bytes(spec.method.as_bytes()).unwrap_or(reqwest::Method::GET);
    let mut request = client.request(method, &full_url);
    request = request
        .header("Authorization", format!("Bearer {token}"))
        .header("Accept", spec.accept.unwrap_or(GITHUB_DEFAULT_ACCEPT))
        .header("X-GitHub-Api-Version", GITHUB_API_VERSION)
        .header("User-Agent", GITHUB_USER_AGENT);
    if let Some(body) = body {
        request = request
            .header("Content-Type", "application/json")
            .body(body.to_string());
    }
    let response = match request.send().await {
        Ok(response) => response,
        Err(e) => {
            let error = if e.is_timeout() {
                format!(
                    "network error: GitHub request timed out after {GITHUB_REQUEST_TIMEOUT_SECS}s"
                )
            } else {
                format!("network error: {e}")
            };
            return GitHubResponse {
                status: 0,
                ok: false,
                body: String::new(),
                error: Some(error),
                rate_remaining: None,
            };
        }
    };
    let status = response.status().as_u16();
    let rate_remaining = response
        .headers()
        .get("x-ratelimit-remaining")
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.parse::<i64>().ok());
    if let Some(content_length) = response
        .headers()
        .get("content-length")
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.parse::<usize>().ok())
        && content_length > GITHUB_MAX_RESPONSE_BODY_BYTES
    {
        return GitHubResponse {
            status,
            ok: false,
            body: String::new(),
            error: Some(format!(
                "GitHub API response exceeds the {GITHUB_MAX_RESPONSE_BODY_BYTES} byte limit"
            )),
            rate_remaining,
        };
    }
    let mut bytes: Vec<u8> = Vec::new();
    let mut stream = response.bytes_stream();
    while let Some(chunk) = stream.next().await {
        match chunk {
            Ok(chunk) => {
                bytes.extend_from_slice(&chunk);
                if bytes.len() > GITHUB_MAX_RESPONSE_BODY_BYTES {
                    return GitHubResponse {
                        status,
                        ok: false,
                        body: String::new(),
                        error: Some(format!(
                            "GitHub API response exceeds the {GITHUB_MAX_RESPONSE_BODY_BYTES} byte limit"
                        )),
                        rate_remaining,
                    };
                }
            }
            Err(e) => {
                return GitHubResponse {
                    status: 0,
                    ok: false,
                    body: String::new(),
                    error: Some(format!("network error: {e}")),
                    rate_remaining: None,
                };
            }
        }
    }
    let body_text = String::from_utf8_lossy(&bytes).into_owned();
    if !(200..300).contains(&status) {
        return GitHubResponse {
            status,
            ok: false,
            body: body_text,
            error: Some(format!("GitHub API error {status}")),
            rate_remaining,
        };
    }
    GitHubResponse {
        status,
        ok: true,
        body: body_text,
        error: None,
        rate_remaining,
    }
}

/// Result shaping mirrors v2 `GitHubToolBase.execute`: errors are
/// `{error} (status {code})\n{body前4000字符}`, successes are
/// `{body}\n\n(GitHub rate limit remaining: {n})` with `(empty response)`
/// for an empty body.
fn format_result(response: GitHubResponse) -> ExecutableToolResult {
    if !response.ok {
        let detail = if response.body.is_empty() {
            String::new()
        } else {
            format!("\n{}", truncate_chars(&response.body, 4000))
        };
        let status = if response.status > 0 {
            format!(" (status {})", response.status)
        } else {
            String::new()
        };
        return err_result(format!(
            "{}{status}{detail}",
            response
                .error
                .unwrap_or_else(|| "GitHub request failed".to_string())
        ));
    }
    let rate = match response.rate_remaining {
        Some(n) => format!("\n\n(GitHub rate limit remaining: {n})"),
        None => String::new(),
    };
    let body = if response.body.is_empty() {
        "(empty response)".to_string()
    } else {
        response.body
    };
    ok_result(format!("{body}{rate}"))
}

fn truncate_chars(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

fn ok_result(content: String) -> ExecutableToolResult {
    ExecutableToolResult {
        content,
        is_error: false,
        note: None,
    }
}

fn err_result(content: String) -> ExecutableToolResult {
    ExecutableToolResult {
        content,
        is_error: true,
        note: None,
    }
}

